//! Rust items from the IR: structs, union enums, `Codec` impls, functions, the `Packet` enum
//! and the helpers they use. The text is unformatted; `gen` runs rustfmt on it.

use std::collections::{BTreeMap, BTreeSet};

use super::body::{self, Dir, Summaries, Summary};
use super::ir::{Enum, Field, Function, Stmt, TypeDef, Union};
use super::model::{self, BOX_OVER, Model, Module};
use super::{consts, names};

type R<T> = Result<T, String>;

/// The first line of every generated file.
pub(crate) const HEADER: &str = "// @generated by cargo xtask gen; do not edit.";

/// Generated file contents.
#[derive(Debug)]
pub(crate) struct Output {
    /// `src/protocol/types.rs`
    pub(crate) types: String,
    /// `src/protocol/packet.rs`
    pub(crate) packet: String,
}

/// Generates both files.
pub(crate) fn generate(m: &Model<'_>) -> R<Output> {
    let sums = summaries(m)?;
    let enums = consts::enum_names()?;
    let mut helpers = BTreeSet::new();
    let mut types = String::new();
    let mut packet = String::new();
    for t in &m.ir.types {
        if model::hand_type(&t.name).is_some() {
            continue;
        }
        let module = model::module_of(&t.name);
        let out = match module {
            Module::Types => &mut types,
            Module::Packet => &mut packet,
        };
        type_items(m, &sums, &enums, t, module, out, &mut helpers)
            .map_err(|e| format!("{}: {e}", t.name))?;
    }
    for f in &m.ir.functions {
        if Model::hand_function(&f.name).is_some() {
            continue;
        }
        let out = match model::module_of(&f.name) {
            Module::Types => &mut types,
            Module::Packet => &mut packet,
        };
        function_items(m, &sums, f, out, &mut helpers).map_err(|e| format!("{}: {e}", f.name))?;
    }
    for e in &m.ir.enums {
        let out = match model::module_of(&e.name) {
            Module::Types => &mut types,
            Module::Packet => &mut packet,
        };
        enum_fn(m, e, out).map_err(|err| format!("{}: {err}", e.name))?;
    }
    packet_enum(m, &mut packet)?;
    types.push_str(&hand_limits(m, &helpers)?);
    let source = &m.ir.source;
    let origin = format!(
        "gophertunnel {} (commit {}), protocol {}, game version {}",
        source.version, source.commit, source.protocol, source.game_version
    );
    let types = format!("{}{types}", helper_items(&helpers, &types, &packet));
    let types_file = format!(
        "{HEADER}\n//! Protocol types generated from the protocol IR: {origin}.\n\n{}\n{types}",
        imports(m, &types, Module::Types),
    );
    let packet_file = format!(
        "{HEADER}\n//! Packets and the [`Packet`] enum generated from the protocol IR: {origin}.\n\n{}\n\
         /// The protocol version these packets implement.\npub const PROTOCOL_VERSION: i32 = {};\n\
         /// The game version these packets implement.\npub const GAME_VERSION: &str = {};\n\n{packet}",
        imports(m, &packet, Module::Packet),
        source.protocol,
        body::str_lit(&source.game_version),
    );
    Ok(Output {
        types: types_file,
        packet: packet_file,
    })
}

/// The `use` lines of a generated file: the protocol items its code names.
fn imports(m: &Model<'_>, text: &str, module: Module) -> String {
    let code: String = text
        .lines()
        .filter(|l| !l.trim_start().starts_with("//"))
        .collect::<Vec<_>>()
        .join("\n");
    let mut candidates: BTreeSet<String> = [
        "Codec",
        "Reader",
        "Writer",
        "Result",
        "Error",
        "length",
        "length_max",
        "AbilityValue",
        "Uuid",
        "Rgba",
    ]
    .into_iter()
    .map(str::to_owned)
    .chain(model::hand_names().map(str::to_owned))
    .collect();
    if module == Module::Packet {
        let local: BTreeSet<&String> = m
            .rust_names
            .values()
            .filter(|(_, md)| *md == Module::Packet)
            .map(|(n, _)| n)
            .collect();
        candidates.extend(
            m.rust_names
                .values()
                .filter(|(_, md)| *md == Module::Types)
                .map(|(n, _)| n.clone())
                .chain(m.interfaces.values().map(|i| i.rust.clone()))
                .filter(|n| !local.contains(n)),
        );
    }
    let used: Vec<String> = candidates
        .into_iter()
        .filter(|c| mentions(&code, c))
        .collect();
    let mut out = format!("use super::{{{}}};\n", used.join(", "));
    if code.contains("nbt::") {
        out.push_str("use crate::nbt;\n");
    }
    out
}

// ----- summaries -----

/// Computes what each function looks like to callers; fallibility comes from lowering the
/// bodies until it no longer changes.
fn summaries(m: &Model<'_>) -> R<Summaries> {
    let mut sums = Summaries::new();
    for f in &m.ir.functions {
        if Model::hand_function(&f.name).is_some() {
            continue;
        }
        let all: Vec<_> = f.receiver.iter().chain(&f.params).collect();
        let used = all
            .iter()
            .map(|p| body::uses_var(&f.body, &p.name))
            .collect();
        let result = if f.results.iter().any(body::is_string) {
            if returns_concat(&f.body) {
                "String"
            } else {
                "&str"
            }
        } else {
            ""
        };
        for decode in [true, false] {
            sums.insert(
                (f.name.clone(), decode),
                Summary {
                    fallible: true,
                    used: Vec::clone(&used),
                    result: result.to_owned(),
                    ..Summary::default()
                },
            );
        }
    }
    // Encode writes: by-value `Copy` parameters a function assigns are returned (in-out).
    for _ in 0..4 {
        let snapshot = sums.clone();
        for f in &m.ir.functions {
            let Some(sum) = sums.get_mut(&(f.name.clone(), false)) else {
                continue;
            };
            let all: Vec<_> = f.receiver.iter().chain(&f.params).collect();
            let mut in_out = Vec::new();
            let mut written = Vec::new();
            for (i, p) in all.iter().enumerate() {
                if !p.by_ref || !f.io {
                    continue;
                }
                if assigns(m, &snapshot, &f.body, &p.name) {
                    if m.is_copy(&p.ty) {
                        in_out.push(i);
                    } else {
                        written.push(i);
                    }
                }
            }
            sum.in_out = in_out;
            sum.written = written;
        }
    }
    for _ in 0..8 {
        let mut changed = false;
        for f in &m.ir.functions {
            if Model::hand_function(&f.name).is_some() {
                continue;
            }
            for decode in [true, false] {
                let key = (f.name.clone(), decode);
                let Some(sum) = sums.get(&key).cloned() else {
                    continue;
                };
                let dir = if decode && f.io {
                    Dir::Decode
                } else {
                    Dir::Encode
                };
                let lowered = body::function(m, &sums, dir, f, &sum)
                    .map_err(|e| format!("{}: {e}", f.name))?;
                if lowered.fallible != sum.fallible {
                    if let Some(s) = sums.get_mut(&key) {
                        s.fallible = lowered.fallible;
                    }
                    changed = true;
                }
            }
        }
        if !changed {
            return Ok(sums);
        }
    }
    Err("function fallibility does not settle".to_owned())
}

fn returns_concat(stmts: &[super::ir::Stmt]) -> bool {
    stmts.iter().any(|s| {
        (s.kind == "return" && s.values.iter().any(|v| v.kind == "binary" && v.op == "+"))
            || returns_concat(&s.then)
            || returns_concat(&s.els)
            || returns_concat(&s.body)
    })
}

/// Whether statements assign the Go variable `name` or a place inside it when encoding.
fn assigns(m: &Model<'_>, sums: &Summaries, stmts: &[super::ir::Stmt], name: &str) -> bool {
    let rooted = |e: &super::ir::Expr| {
        let mut cur = Some(e);
        while let Some(c) = cur {
            if c.kind == "var" {
                return c.name == name;
            }
            cur = c.x.as_deref();
        }
        false
    };
    stmts.iter().any(|s| {
        let direct = match s.kind.as_str() {
            "assign" => s.lhs.iter().any(rooted),
            "call" if s.target == "enum" => m
                .enums
                .get(s.func.as_str())
                .and_then(|e| e.params.iter().position(|p| p.name == e.output))
                .and_then(|i| s.args.get(i))
                .is_some_and(rooted),
            "call" if s.target == "function" => {
                sums.get(&(s.func.clone(), false)).is_some_and(|sum| {
                    let shift = usize::from(s.recv.is_some());
                    sum.in_out
                        .iter()
                        .chain(&sum.written)
                        .filter_map(|i| i.checked_sub(shift))
                        .filter_map(|i| s.args.get(i))
                        .any(rooted)
                })
            }
            _ => false,
        };
        direct
            || assigns(m, sums, &s.body, name)
            || assigns(m, sums, &s.then, name)
            || assigns(m, sums, &s.els, name)
            || s.cases.iter().any(|c| assigns(m, sums, &c.body, name))
    })
}

// ----- docs -----

/// `///` lines of a text the generator wrote; blank lines separate paragraphs.
pub(crate) fn doc(text: &str, indent: &str) -> String {
    let mut out = String::new();
    let paragraphs: Vec<String> = text
        .split("\n\n")
        .map(|p| p.split_whitespace().collect::<Vec<_>>().join(" "))
        .filter(|p| !p.is_empty())
        .collect();
    for (i, p) in paragraphs.iter().enumerate() {
        if i > 0 {
            put!(out, "{indent}///\n");
        }
        put!(out, "{indent}/// {}\n", markdown(p));
    }
    out
}

/// Escapes a paragraph for rustdoc and `clippy::doc_markdown`: code-like words go in
/// backticks, brackets and angle brackets are escaped, and URLs become autolinks.
fn markdown(p: &str) -> String {
    let balanced = p.matches('`').count().is_multiple_of(2);
    let mut in_code = false;
    let mut words = Vec::new();
    for word in p.split(' ') {
        let ticks = word.matches('`').count();
        if balanced && (in_code || ticks > 0) {
            if ticks % 2 == 1 {
                in_code = !in_code;
            }
            words.push(word.to_owned());
            continue;
        }
        let word = word.replace('`', "");
        let start = word
            .find(|c: char| c.is_alphanumeric())
            .unwrap_or(word.len());
        let end = word
            .rfind(|c: char| c.is_alphanumeric() || c == ')')
            .map_or(start, |i| i + 1);
        let (lead, core, trail) = (
            word.get(..start).unwrap_or_default(),
            word.get(start..end).unwrap_or_default(),
            word.get(end..).unwrap_or_default(),
        );
        if core.starts_with("http://") || core.starts_with("https://") {
            words.push(format!("{}<{core}>{}", escape(lead), escape(trail)));
        } else if code_like(core) {
            words.push(format!("{}`{core}`{}", escape(lead), escape(trail)));
        } else {
            words.push(escape(&word));
        }
    }
    words.join(" ")
}

fn escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        if matches!(c, '[' | ']' | '<' | '>' | '*' | '_' | '\\' | '#' | '|') {
            out.push('\\');
        }
        out.push(c);
    }
    out
}

/// Words `clippy::doc_markdown` would want in backticks.
fn code_like(word: &str) -> bool {
    let camel = word.starts_with(|c: char| c.is_ascii_uppercase())
        && word.chars().filter(char::is_ascii_uppercase).count() > 1
        && word.chars().any(|c| c.is_ascii_lowercase());
    camel
        || word.contains('_')
        || word.contains("::")
        || word.contains('(')
        || word.contains('.') && word.chars().any(|c| c.is_ascii_uppercase())
}

/// A sentence from a Go name: `EntityRuntimeID` → `The entity runtime ID.`
fn name_doc(go: &str) -> String {
    let words: Vec<String> = names::words(go)
        .into_iter()
        .map(|w| {
            if w.chars().skip(1).any(|c| c.is_ascii_uppercase()) {
                w
            } else {
                w.to_ascii_lowercase()
            }
        })
        .collect();
    format!("The {}.", words.join(" "))
}

/// The doc of a named type: the packet's ID and sender for a packet, else the Go name.
fn type_doc(m: &Model<'_>, t: &TypeDef) -> R<String> {
    let Some(p) = m.ir.packets.iter().find(|p| p.ty == t.name) else {
        return Ok(format!("gophertunnel `{}`.", t.name));
    };
    let sender = match p.direction.as_str() {
        "client" => "the client",
        "server" => "the server",
        "both" => "the client and the server",
        other => return Err(format!("unknown packet direction {other}")),
    };
    Ok(format!(
        "Packet `{}` (ID {}), sent by {sender}.",
        t.name, p.id
    ))
}

/// The doc of a struct field from the IR alone: its name, the wire form the type's `Marshal`
/// first writes it with, the constants enum of its values and its Mojang limits.
fn field_doc(
    m: &Model<'_>,
    enums: &BTreeMap<&str, Option<String>>,
    t: &TypeDef,
    f: &Field,
) -> String {
    let mut text = name_doc(&f.name);
    if let Some(wire) = t
        .marshal
        .as_ref()
        .and_then(|b| wire_form(&b.stmts, &b.receiver, &f.name))
    {
        put!(text, " Wire form: {wire}.");
    }
    if let Some(e) = field_enum(enums, t, f) {
        put!(text, " Values: [`{e}`](super::consts::{e}).");
    }
    let value = if f.ty.kind == "optional" {
        f.ty.elem.as_deref().unwrap_or(&f.ty)
    } else {
        &f.ty
    };
    let bytes = value.kind == "basic"
        || value
            .elem
            .as_deref()
            .is_some_and(|e| e.kind == "basic" && e.name == "uint8");
    let unit = if bytes { "bytes" } else { "elements" };
    if let Some(max) = m.limits.get(&format!("{}.{}", t.name, f.name)) {
        put!(text, " Mojang limit: {max} {unit}.");
    }
    if let Some(max) = m.limits.get(&format!("{}.{}[]", t.name, f.name)) {
        put!(text, " Mojang limit per element: {max} bytes.");
    }
    doc(&text, "    ")
}

/// How the first statement of a `Marshal` body that names `recv.field` writes it.
fn wire_form(stmts: &[Stmt], recv: &str, field: &str) -> Option<String> {
    for s in stmts {
        let here = s.place.as_ref().is_some_and(|p| {
            p.kind == "field"
                && p.name == field
                && p.x
                    .as_deref()
                    .is_some_and(|x| x.kind == "var" && x.name == recv)
        });
        if here {
            return match s.kind.as_str() {
                "io" => Some(format!("`{}`", s.method)),
                "integer_func" => s
                    .body
                    .iter()
                    .find(|b| b.kind == "io")
                    .map(|b| format!("`{}`", b.method)),
                // An empty prefix: the count is a statement of its own before the slice.
                "slice" if s.prefix.is_empty() => None,
                "slice" => Some(format!("a list after a `{}` count", s.prefix)),
                "optional" => Some("a bool, then the value when it is set".to_owned()),
                _ => None,
            };
        }
        let nested = [&s.body, &s.then, &s.els]
            .into_iter()
            .chain(s.cases.iter().map(|c| &c.body))
            .find_map(|b| wire_form(b, recv, field));
        if nested.is_some() {
            return nested;
        }
    }
    None
}

/// The constants enum of an integer or string field: the first group named like the field,
/// alone or after the type's name, in the type's package first. A group that is no enum (bit
/// positions, open values) stops the search.
fn field_enum<'a>(
    enums: &'a BTreeMap<&str, Option<String>>,
    t: &TypeDef,
    f: &Field,
) -> Option<&'a String> {
    if f.ty.kind != "basic" {
        return None;
    }
    let (package, local) = t.name.split_once('.')?;
    let other = if package == "packet" {
        "protocol"
    } else {
        "packet"
    };
    [package, other]
        .into_iter()
        .find_map(|p| {
            enums
                .get(format!("{p}.{}", f.name).as_str())
                .or_else(|| enums.get(format!("{p}.{local}{}", f.name).as_str()))
        })?
        .as_ref()
}

// ----- types -----

fn type_items(
    m: &Model<'_>,
    sums: &Summaries,
    enums: &BTreeMap<&str, Option<String>>,
    t: &TypeDef,
    module: Module,
    out: &mut String,
    helpers: &mut BTreeSet<String>,
) -> R<()> {
    let rust = m.named(&t.name, module)?;
    let type_doc = doc(&type_doc(m, t)?, "");
    match t.kind.as_str() {
        "struct" => {
            out.push_str(&type_doc);
            out.push_str("#[derive(Debug, Clone, PartialEq, Default)]\n");
            let field_names = t
                .fields
                .iter()
                .map(|f| {
                    body::field_rust_name(&t.name, &f.name)
                        .map(|n| n.trim_start_matches("r#").to_owned())
                })
                .collect::<R<Vec<_>>>()?;
            if struct_field_names_fires(&rust, &field_names) {
                out.push_str("#[expect(clippy::struct_field_names, reason = \"consistency: field names mirror gophertunnel\")]\n");
            }
            if t.fields.is_empty() {
                put!(out, "pub struct {rust} {{}}\n\n");
            } else {
                put!(out, "pub struct {rust} {{\n");
                for f in &t.fields {
                    let name = body::field_rust_name(&t.name, &f.name)?;
                    let ty = if f.ty.kind == "any" {
                        if !m.ability_fields.contains(&(t.name.clone(), f.name.clone())) {
                            return Err(format!(
                                "field {} of type any is not an AbilityValue",
                                f.name
                            ));
                        }
                        "AbilityValue".to_owned()
                    } else {
                        m.rust_type(&f.ty, module)?
                    };
                    out.push_str(&field_doc(m, enums, t, f));
                    put!(out, "    pub {name}: {ty},\n");
                }
                out.push_str("}\n\n");
            }
        }
        "array" => {
            let under = t
                .underlying
                .as_ref()
                .ok_or("array without underlying type")?;
            out.push_str(&type_doc);
            put!(
                out,
                "pub type {rust} = {};\n\n",
                m.rust_type(under, module)?
            );
        }
        "interface" => return union_items(m, t, out),
        other => return Err(format!("unsupported type kind {other}")),
    }
    if let Some(b) = &t.marshal {
        let dec = body::marshal(m, sums, Dir::Decode, module, &t.name, &b.receiver, &b.stmts)?;
        let enc = body::marshal(m, sums, Dir::Encode, module, &t.name, &b.receiver, &b.stmts)?;
        helpers.extend(dec.helpers.iter().cloned());
        helpers.extend(enc.helpers.iter().cloned());
        let target = if t.kind == "array" {
            m.rust_type(
                t.underlying
                    .as_ref()
                    .ok_or("array without underlying type")?,
                module,
            )?
        } else {
            rust
        };
        let r = if mentions(&dec.body, "r") { "r" } else { "_r" };
        let w = if mentions(&enc.body, "w") { "w" } else { "_w" };
        put!(
            out,
            "impl Codec for {target} {{\n\
             fn decode({r}: &mut Reader<'_>) -> Result<Self> {{\n{}\n}}\n\n\
             fn encode(&self, {w}: &mut Writer) -> Result<()> {{\n{}\n}}\n}}\n\n",
            ok_tail(&dec.body),
            ok_tail(&enc.body),
        );
    }
    Ok(())
}

/// Whether `clippy::struct_field_names` (threshold 3) fires on a struct: a field starts or ends
/// with the struct's name, or all fields share a first or last word.
fn struct_field_names_fires(name: &str, fields: &[String]) -> bool {
    if fields.len() < 3 {
        return false;
    }
    let mut snake = String::new();
    for (i, c) in name.chars().enumerate() {
        if c.is_uppercase() {
            if i != 0 {
                snake.push('_');
            }
            snake.extend(c.to_lowercase());
        } else {
            snake.push(c);
        }
    }
    let item: Vec<&str> = snake.split('_').collect();
    for f in fields {
        let words: Vec<&str> = f.split('_').collect();
        if words.len() >= item.len() {
            if words.iter().zip(&item).all(|(a, b)| a == b) {
                return true;
            }
            if words.len() > item.len()
                && words
                    .iter()
                    .rev()
                    .zip(item.iter().rev())
                    .all(|(a, b)| a == b)
            {
                return true;
            }
        }
    }
    let Some(first) = fields.first() else {
        return false;
    };
    let mut pre: Vec<&str> = first.split('_').collect();
    let mut post: Vec<&str> = pre.iter().rev().copied().collect();
    for f in fields {
        let words: Vec<&str> = f.split('_').collect();
        if words.len() == 1 {
            return false;
        }
        pre = pre
            .into_iter()
            .zip(&words)
            .take_while(|(a, b)| a == *b)
            .map(|e| e.0)
            .collect();
        post = post
            .into_iter()
            .zip(words.iter().rev())
            .take_while(|(a, b)| a == *b)
            .map(|e| e.0)
            .collect();
    }
    !pre.is_empty() || !post.is_empty()
}

/// A trait method body always returns `Result`; a body that never fails was printed without
/// `Ok`.
fn ok_tail(body: &str) -> String {
    if body.trim().is_empty() {
        return "Ok(())".to_owned();
    }
    body.to_owned()
}

fn mentions(code: &str, name: &str) -> bool {
    let bytes = code.as_bytes();
    let ident = |b: Option<&u8>| b.is_some_and(|b| b.is_ascii_alphanumeric() || *b == b'_');
    let mut start = 0;
    while let Some(pos) = code.get(start..).and_then(|c| c.find(name)) {
        let at = start + pos;
        let end = at + name.len();
        let before = at.checked_sub(1).and_then(|i| bytes.get(i));
        if !ident(before) && !ident(bytes.get(end)) && !matches!(before, Some(b'.' | b'\'' | b':'))
        {
            return true;
        }
        start = end;
    }
    false
}

/// The union lookups of an interface.
fn union_fns<'a>(m: &Model<'a>, names: &[String]) -> R<Vec<&'a Union>> {
    names
        .iter()
        .map(|n| {
            m.unions
                .get(n.as_str())
                .copied()
                .ok_or_else(|| format!("unknown union {n}"))
        })
        .collect()
}

#[expect(
    clippy::too_many_lines,
    reason = "consistency: one union enum and its impl in one place"
)]
fn union_items(m: &Model<'_>, t: &TypeDef, out: &mut String) -> R<()> {
    let info = m.interfaces.get(&t.name).ok_or("interface without union")?;
    let by_id = union_fns(m, std::slice::from_ref(&info.by_id))?;
    let by_id = by_id.first().ok_or("no id lookup")?;
    let id_ty = m.rust_type(&by_id.id_type, Module::Types)?;
    let rust = &info.rust;
    let variant_type = |go: &str| m.named(go, Module::Types);
    let boxed = |go: &str| {
        m.variant_size(go) == 8
            && m.types
                .get(go)
                .is_some_and(|d| d.fields.iter().map(|f| m.size(&f.ty)).sum::<u64>() > BOX_OVER)
    };
    out.push_str(&doc(&format!("gophertunnel `{}`.", t.name), ""));
    out.push_str("#[derive(Debug, Clone, PartialEq)]\n");
    put!(out, "pub enum {rust} {{\n");
    for (go, variant) in &info.variants {
        let ty = variant_type(go)?;
        let ty = if boxed(go) { format!("Box<{ty}>") } else { ty };
        put!(
            out,
            "    /// The [`{}`] variant.\n    {variant}({ty}),\n",
            variant_type(go)?
        );
    }
    out.push_str("}\n\n");
    let (first_go, first) = info.variants.first().ok_or("union without variants")?;
    let new = |go: &str, variant: &str| -> R<String> {
        Ok(if boxed(go) {
            format!("Self::{variant}(Box::default())")
        } else {
            format!("Self::{variant}({}::default())", variant_type(go)?)
        })
    };
    put!(
        out,
        "impl Default for {rust} {{\nfn default() -> Self {{\n{}\n}}\n}}\n\nimpl {rust} {{\n",
        new(first_go, first)?
    );
    // ID to variant.
    put!(
        out,
        "/// The variant with this ID and default fields (gophertunnel `{}`), or `None` for an unknown ID.\n",
        model::local(&by_id.name)
    );
    put!(
        out,
        "pub fn from_id(id: {id_ty}) -> Option<Self> {{\nSome(match id {{\n"
    );
    for entry in &by_id.entries {
        let [Some(go)] = entry.variants.as_slice() else {
            continue;
        };
        let variant = &info
            .variants
            .iter()
            .find(|(g, _)| g == go)
            .ok_or("unknown variant")?
            .1;
        let ids = entry.ids.iter().map(id_value).collect::<R<Vec<_>>>()?;
        put!(out, "{} => {},\n", body::compress(&ids), new(go, variant)?);
    }
    out.push_str("_ => return None,\n})\n}\n\n");
    // Variant to IDs.
    for u in union_fns(m, &info.by_type)? {
        let full = info.variants.iter().all(|(g, _)| {
            u.entries
                .iter()
                .any(|e| e.variants.iter().any(|v| v.as_deref() == Some(g)))
        });
        let method = if u.id_type == by_id.id_type && full {
            "id".to_owned()
        } else {
            let local = model::local(&u.name).trim_start_matches("lookup");
            let iface = model::local(&t.name);
            names::snake(local.strip_prefix(iface).unwrap_or(local), &u.name)?
        };
        let ty = m.rust_type(&u.id_type, Module::Types)?;
        let ret = if full {
            ty.clone()
        } else {
            format!("Option<{ty}>")
        };
        put!(
            out,
            "/// The {} of the variant (gophertunnel `{}`).\n",
            method.replace('_', " "),
            model::local(&u.name)
        );
        put!(out, "pub fn {method}(&self) -> {ret} {{\nmatch self {{\n");
        let mut missing: Vec<String> = Vec::new();
        for (go, variant) in &info.variants {
            if !u
                .entries
                .iter()
                .any(|e| e.variants.iter().any(|v| v.as_deref() == Some(go.as_str())))
            {
                missing.push(format!("Self::{variant}(_)"));
            }
        }
        for entry in &u.entries {
            let pats: Vec<String> = entry
                .variants
                .iter()
                .flatten()
                .filter_map(|g| {
                    info.variants
                        .iter()
                        .find(|(x, _)| x == g)
                        .map(|(_, v)| format!("Self::{v}(_)"))
                })
                .collect();
            if pats.is_empty() {
                continue;
            }
            let id = entry
                .ids
                .first()
                .map(id_value)
                .transpose()?
                .ok_or("row without id")?;
            let value = if full { id } else { format!("Some({id})") };
            put!(out, "{} => {value},\n", pats.join(" | "));
        }
        if !missing.is_empty() {
            put!(out, "{} => None,\n", missing.join(" | "));
        }
        out.push_str("}\n}\n\n");
        // Extra results: the wire name of item descriptors.
        let extras = u.results.len().saturating_sub(2);
        for k in 0..extras {
            let name = names::union_extra(&u.name, k)?;
            put!(
                out,
                "/// The {} of the variant (gophertunnel `{}`).\n",
                name.replace('_', " "),
                model::local(&u.name)
            );
            put!(
                out,
                "pub fn {name}(&self) -> &'static str {{\nmatch self {{\n"
            );
            for entry in &u.entries {
                let pats: Vec<String> = entry
                    .variants
                    .iter()
                    .flatten()
                    .filter_map(|g| {
                        info.variants
                            .iter()
                            .find(|(x, _)| x == g)
                            .map(|(_, v)| format!("Self::{v}(_)"))
                    })
                    .collect();
                if pats.is_empty() {
                    continue;
                }
                let value = entry
                    .extra
                    .get(k)
                    .and_then(|e| e.value.clone())
                    .ok_or("row without extra")?;
                put!(out, "{} => {},\n", pats.join(" | "), body::str_lit(&value));
            }
            out.push_str("}\n}\n\n");
        }
    }
    // Bodies.
    out.push_str("/// Reads the body of the same variant.\npub(crate) fn decode_variant(&self, r: &mut Reader<'_>) -> Result<Self> {\nOk(match self {\n");
    for (go, variant) in &info.variants {
        let ty = body::type_path(&variant_type(go)?);
        if boxed(go) {
            put!(
                out,
                "Self::{variant}(_) => Self::{variant}(Box::new({ty}::decode(r)?)),\n"
            );
        } else {
            put!(
                out,
                "Self::{variant}(_) => Self::{variant}({ty}::decode(r)?),\n"
            );
        }
    }
    out.push_str("})\n}\n\n/// Writes the body of the variant.\npub(crate) fn encode_variant(&self, w: &mut Writer) -> Result<()> {\nmatch self {\n");
    for (_, variant) in &info.variants {
        put!(out, "Self::{variant}(x) => x.encode(w),\n");
    }
    out.push_str("}\n}\n}\n\n");
    Ok(())
}

fn id_value(e: &super::ir::Expr) -> R<String> {
    e.value
        .as_deref()
        .map(body::int_lit)
        .ok_or_else(|| "id without value".to_owned())
}

// ----- functions -----

fn function_items(
    m: &Model<'_>,
    sums: &Summaries,
    f: &Function,
    out: &mut String,
    helpers: &mut BTreeSet<String>,
) -> R<()> {
    let dirs: &[(bool, Dir)] = if f.io {
        &[(true, Dir::Decode), (false, Dir::Encode)]
    } else {
        &[(true, Dir::Encode)]
    };
    for &(decode, dir) in dirs {
        let sum = sums.get(&(f.name.clone(), decode)).ok_or("no summary")?;
        let lowered = body::function(m, sums, dir, f, sum)?;
        helpers.extend(lowered.helpers.iter().cloned());
        let (prefix, io) = match (f.io, dir) {
            (false, _) => ("", String::new()),
            (true, Dir::Decode) => ("decode_", "r: &mut Reader<'_>, ".to_owned()),
            (true, Dir::Encode) => ("encode_", "w: &mut Writer, ".to_owned()),
        };
        let name = body::fn_name(&f.name, prefix)?;
        let mut results: Vec<String> = Vec::new();
        for t in &f.results {
            results.push(if body::is_string(t) {
                if sum.result == "String" {
                    "String".to_owned()
                } else if f
                    .params
                    .iter()
                    .chain(&f.receiver)
                    .any(|p| body::is_string(&p.ty))
                {
                    "&str".to_owned()
                } else {
                    "&'static str".to_owned()
                }
            } else if t.kind == "error" {
                "Option<&'static str>".to_owned()
            } else {
                m.rust_type(t, model::module_of(&f.name))?
            });
        }
        let all: Vec<_> = f.receiver.iter().chain(&f.params).collect();
        if dir == Dir::Encode && f.io {
            for &i in &sum.in_out {
                let p = all.get(i).ok_or("in-out parameter missing")?;
                results.push(m.rust_type(&p.ty, model::module_of(&f.name))?);
            }
        }
        let value = match results.len() {
            0 => "()".to_owned(),
            1 => results.concat(),
            _ => format!("({})", results.join(", ")),
        };
        let ret = if lowered.fallible {
            format!(" -> Result<{value}>")
        } else if value == "()" {
            String::new()
        } else {
            format!(" -> {value}")
        };
        let what = match dir {
            Dir::Decode if f.io => "Reads",
            Dir::Encode if f.io => "Writes",
            _ => "Computes",
        };
        out.push_str(&doc(
            &format!("{what} like gophertunnel `{}`.", model::local(&f.name)),
            "",
        ));
        let vis = vis(&f.name);
        put!(
            out,
            "{vis}fn {name}({io}{}){ret} {{\n{}\n}}\n\n",
            lowered.params,
            lowered.body
        );
    }
    Ok(())
}

/// Items in `types.rs` used from `packet.rs` are `pub(crate)`.
fn vis(go: &str) -> &'static str {
    if model::module_of(go) == Module::Types {
        "pub(crate) "
    } else {
        ""
    }
}

fn enum_fn(m: &Model<'_>, e: &Enum, out: &mut String) -> R<()> {
    let name = body::fn_name(&e.name, "")?;
    let on = e
        .params
        .iter()
        .find(|p| p.name == e.on)
        .ok_or("enum without switch parameter")?;
    let vis = vis(&e.name);
    let module = model::module_of(&e.name);
    if e.output == "return" {
        let [result] = e.results.as_slice() else {
            return Err("enum with several results".to_owned());
        };
        if !body::is_string(result) || body::is_string(&on.ty) {
            return Err("unsupported returning enum".to_owned());
        }
        let ty = m.rust_type(&on.ty, module)?;
        let default = match e.default.as_slice() {
            [s] if s.kind == "return" => s
                .values
                .first()
                .and_then(|v| v.value.clone())
                .ok_or("default without value")?,
            _ => return Err("unsupported enum default".to_owned()),
        };
        put!(
            out,
            "/// The wire string of a value (gophertunnel `{}`).\n{vis}fn {name}(x: {ty}) -> &'static str {{\nmatch x {{\n",
            model::local(&e.name)
        );
        for c in &e.cases {
            let pats = c.values.iter().map(id_value).collect::<R<Vec<_>>>()?;
            let value = c
                .results
                .first()
                .and_then(|v| v.value.clone())
                .ok_or("case without result")?;
            put!(
                out,
                "{} => {},\n",
                body::compress(&pats),
                body::str_lit(&value)
            );
        }
        put!(out, "_ => {},\n}}\n}}\n\n", body::str_lit(&default));
        return Ok(());
    }
    let output = e
        .params
        .iter()
        .find(|p| p.name == e.output)
        .ok_or("enum without output parameter")?;
    if !body::is_string(&on.ty) {
        return Err("unsupported assigning enum".to_owned());
    }
    let ty = m.rust_type(&output.ty, module)?;
    let [err] = e.default.as_slice() else {
        return Err("assigning enum without an error default".to_owned());
    };
    if err.kind != "error" || err.error != "invalid_value" {
        return Err("unsupported enum default".to_owned());
    }
    let text = |x: &Option<super::ir::Expr>| {
        x.as_ref()
            .and_then(|e| e.value.clone())
            .ok_or("error without text")
    };
    put!(
        out,
        "/// The value of a wire string (gophertunnel `{}`).\n{vis}fn {name}(s: &str) -> Result<{ty}> {{\nOk(match s {{\n",
        model::local(&e.name)
    );
    for c in &e.cases {
        let pats = c
            .values
            .iter()
            .map(|v| {
                v.value
                    .as_deref()
                    .map(body::str_lit)
                    .ok_or("case without value")
            })
            .collect::<Result<Vec<_>, _>>()?;
        let value = c
            .results
            .first()
            .and_then(|v| v.value.clone())
            .ok_or("case without result")?;
        put!(out, "{} => {},\n", pats.join(" | "), body::int_lit(&value));
    }
    put!(
        out,
        "_ => return Err(Error::InvalidValue {{ field: {}, reason: {} }}),\n}})\n}}\n\n",
        body::str_lit(&text(&err.field)?),
        body::str_lit(&text(&err.reason)?),
    );
    Ok(())
}

// ----- packets -----

fn packet_enum(m: &Model<'_>, out: &mut String) -> R<()> {
    let mut rows = Vec::new();
    for p in &m.ir.packets {
        let rust = m.named(&p.ty, Module::Packet)?;
        let size = m
            .types
            .get(p.ty.as_str())
            .map_or(0, |d| d.fields.iter().map(|f| m.size(&f.ty)).sum::<u64>());
        rows.push((p, rust, size > BOX_OVER));
    }
    out.push_str(
        "/// A packet of the Bedrock protocol: one variant per packet ID. Large packets are boxed so \
         that the enum stays small to move.\n#[derive(Debug, Clone, PartialEq)]\npub enum Packet {\n",
    );
    for (p, rust, boxed) in &rows {
        let ty = if *boxed {
            format!("Box<{rust}>")
        } else {
            rust.clone()
        };
        put!(
            out,
            "    /// The [`{rust}`] packet (ID {}).\n    {rust}({ty}),\n",
            p.id
        );
    }
    out.push_str("}\n\nimpl Packet {\n");
    out.push_str("/// The packet ID.\npub fn id(&self) -> u32 {\nmatch self {\n");
    for (p, rust, _) in &rows {
        put!(out, "Self::{rust}(_) => {},\n", p.id);
    }
    out.push_str("}\n}\n\n");
    out.push_str("/// A packet of this ID with default fields, or `None` for an unknown ID.\npub fn from_id(id: u32) -> Option<Self> {\nSome(match id {\n");
    for (p, rust, boxed) in &rows {
        let value = if *boxed {
            "Box::default()".to_owned()
        } else {
            format!("{rust}::default()")
        };
        put!(out, "{} => Self::{rust}({value}),\n", p.id);
    }
    out.push_str("_ => return None,\n})\n}\n\n");
    for (dir, name, what) in [
        ("client", "is_from_client", "clients"),
        ("server", "is_from_server", "servers"),
    ] {
        let ids: Vec<String> = rows
            .iter()
            .filter(|(p, _, _)| p.direction == dir || p.direction == "both")
            .map(|(p, _, _)| p.id.to_string())
            .collect();
        put!(
            out,
            "/// Whether {what} send the packet with this ID (gophertunnel's {dir} packet pool). A server \
             accepts only packets from clients.\npub const fn {name}(id: u32) -> bool {{\nmatches!(id, {})\n}}\n\n",
            body::compress(&ids)
        );
    }
    out.push_str(
        "/// Decodes the payload of a packet with this ID: the bytes after the packet header. Every \
         byte must be part of the packet.\n///\n/// `budget` is the allocation budget left for the \
         batch the packet came in; decoding takes what the packet allocates from \
         it. `shield_id` is the shield's item network ID, which changes the item wire format.\n\
         pub fn decode(id: u32, payload: &[u8], budget: &mut usize, shield_id: i32) -> Result<Self> {\n\
         let mut r = Reader::new(payload, *budget, shield_id);\n\
         let packet = Self::decode_body(id, &mut r);\n*budget = r.budget();\nlet packet = packet?;\n\
         if !r.remaining().is_empty() {\nreturn Err(Error::InvalidValue { field: \"packet\", reason: \"bytes after the packet\" });\n}\n\
         Ok(packet)\n}\n\n\
         fn decode_body(id: u32, r: &mut Reader<'_>) -> Result<Self> {\nOk(match id {\n",
    );
    for (p, rust, boxed) in &rows {
        if *boxed {
            put!(
                out,
                "{} => Self::{rust}(Box::new({rust}::decode(r)?)),\n",
                p.id
            );
        } else {
            put!(out, "{} => Self::{rust}({rust}::decode(r)?),\n", p.id);
        }
    }
    out.push_str(
        "_ => return Err(Error::UnknownEnum { name: \"packet id\", value: id.into() }),\n})\n}\n\n\
         /// Appends the payload of the packet (without the packet header) to `out`. On an error \
         `out` is left as it was. `shield_id` is the shield's item network ID.\n\
         pub fn encode(&self, out: &mut Vec<u8>, shield_id: i32) -> Result<()> {\n\
         let start = out.len();\nlet mut w = Writer::new(std::mem::take(out), shield_id);\n\
         let result = match self {\n",
    );
    for (_, rust, _) in &rows {
        put!(out, "Self::{rust}(x) => x.encode(&mut w),\n");
    }
    out.push_str(
        "};\n*out = w.into_inner();\nif result.is_err() {\nout.truncate(start);\n}\nresult\n}\n}\n",
    );
    Ok(())
}

// ----- helpers -----

/// Limits the client also applies to what it receives, for which Anchor builds a list or string
/// from game state or user input: the code that builds it uses the constant.
const SEND_LIMITS: &[&str] = &[
    "packet.BossEvent.BossBarTitle",
    "packet.PlayerEnchantOptions.Options",
    "packet.PlayerList.Entries",
    "packet.Text.Message",
    "packet.Text.Parameters",
    "packet.Text.SourceName",
    "protocol.Command.Description",
];

/// Checks that the decoders apply every limit in `Model::limits`, and returns the constants of
/// the limits of hand-written types, which their hand codecs use, and of [`SEND_LIMITS`].
fn hand_limits(m: &Model<'_>, helpers: &BTreeSet<String>) -> R<String> {
    if let Some(key) = SEND_LIMITS.iter().find(|k| !m.limits.contains_key(**k)) {
        return Err(format!("send limit {key} is not a protocol limit"));
    }
    let mut out = String::new();
    for (key, max) in &m.limits {
        let (ty, field) = key
            .rsplit_once('.')
            .ok_or_else(|| format!("limit {key} names no field"))?;
        let hand = model::hand_type(ty).is_some();
        if !hand && !helpers.contains(&format!("{}{key}", body::LIMIT_USED)) {
            return Err(format!(
                "limit {key} applies to no string or list read of the decoders"
            ));
        }
        let user = if hand {
            "for its hand codec"
        } else if SEND_LIMITS.contains(&key.as_str()) {
            "for what Anchor sends"
        } else {
            continue;
        };
        let local = ty.rsplit_once('.').map_or(ty, |(_, l)| l);
        let name = names::screaming(&format!("{local}{field}MaxLen"), key)?;
        put!(
            out,
            "/// The most bytes or elements of gophertunnel `{key}` (Mojang `maxLength`, \
             `maxItems`), {user}.\npub(crate) const {name}: usize = {};\n\n",
            body::int_lit(&max.to_string())
        );
    }
    Ok(out)
}

/// The helper items the generated code uses, in `types.rs`.
fn helper_items(used: &BTreeSet<String>, types: &str, packet: &str) -> String {
    let mut out = String::new();
    let all = format!("{types}{packet}");
    for (prefix, method) in [
        ("varuint32", "varuint32"),
        ("uint8", "uint8"),
        ("uint32", "uint32"),
    ] {
        if all.contains(&format!("list_{prefix}(")) {
            if out.is_empty() {
                out.push_str("impl Reader<'_> {\n");
            }
            put!(
                out,
                "/// A list with a {method} count, under the list limits.\n\
                 pub(crate) fn list_{prefix}<T>(&mut self, f: impl FnMut(&mut Self) -> Result<T>) -> Result<Vec<T>> {{\n\
                 let count = self.{method}()?;\nself.list(count.into(), f)\n}}\n\n"
            );
        }
        if all.contains(&format!("list_{prefix}_max(")) {
            if out.is_empty() {
                out.push_str("impl Reader<'_> {\n");
            }
            put!(
                out,
                "/// A list with a {method} count of a field that holds at most `max` elements.\n\
                 pub(crate) fn list_{prefix}_max<T>(&mut self, max: usize, f: impl FnMut(&mut Self) -> Result<T>) -> Result<Vec<T>> {{\n\
                 let count = self.{method}()?;\nself.list_max(count.into(), max, f)\n}}\n\n"
            );
        }
    }
    if !out.is_empty() {
        out.push_str("}\n\n");
    }
    if used.contains("go_index") {
        out.push_str(
            "/// Go's `items[i]` without the panic: an index outside `items` is an error.\n\
             pub(crate) fn go_index<T, I: TryInto<usize>>(items: &[T], i: I) -> Result<&T> {\n\
             i.try_into().ok().and_then(|i| items.get(i)).ok_or(Error::InvalidValue { field: \"index\", reason: \"out of range\" })\n}\n\n",
        );
    }
    if used.contains("go_prefix") {
        out.push_str(
            "/// Go's `items[:n]` without the panic: a length past `items` is an error.\n\
             pub(crate) fn go_prefix<T, I: TryInto<usize>>(items: &[T], n: I) -> Result<&[T]> {\n\
             n.try_into().ok().and_then(|n| items.get(..n)).ok_or(Error::InvalidValue { field: \"index\", reason: \"out of range\" })\n}\n\n",
        );
    }
    for name in used {
        let Some(pair) = name.strip_prefix("go_") else {
            continue;
        };
        let Some((from, to)) = pair.split_once("_to_") else {
            continue;
        };
        out.push_str(&conversion(from, to));
    }
    out
}

/// A Go integer conversion helper: Go keeps the low bits.
fn conversion(from: &str, to: &str) -> String {
    let fixed_bits = |p: &str| match p {
        "u8" | "i8" => 8,
        "u16" | "i16" => 16,
        "u32" | "i32" => 32,
        _ => 64,
    };
    let (fb, tb) = (fixed_bits(from), fixed_bits(to));
    let from_signed = from.starts_with('i');
    let to_signed = to.starts_with('i');
    let doc = format!("/// Go's `{to}(x)` for a `{from}` `x`, which keeps the low bits.\n");
    if from == "usize" && to == "i64" {
        return "/// Go's `int(len)`: lengths are below `isize::MAX`.\n\
             pub(crate) fn go_usize_to_i64(x: usize) -> i64 {\ni64::try_from(x).unwrap_or(i64::MAX)\n}\n\n".to_string();
    }
    let truncation = match (from == "usize", to == "usize") {
        (true, false) => tb <= 32,
        (false, true) => fb == 64,
        _ => tb < fb,
    };
    let sign_loss = from_signed && !to_signed;
    let wrap = !from_signed
        && to_signed
        && match (from == "usize", to == "usize") {
            (true, false) => tb <= 32,
            (false, true) => fb == 64,
            _ => tb == fb,
        };
    let mut lints = Vec::new();
    if truncation {
        lints.push("clippy::cast_possible_truncation");
    }
    if sign_loss {
        lints.push("clippy::cast_sign_loss");
    }
    if wrap {
        lints.push("clippy::cast_possible_wrap");
    }
    let expect = if lints.is_empty() {
        String::new()
    } else {
        format!(
            "#[expect({}, reason = \"consistency: Go integer conversions keep the low bits\")]\n",
            lints.join(", ")
        )
    };
    format!("{doc}{expect}pub(crate) fn go_{from}_to_{to}(x: {from}) -> {to} {{\nx as {to}\n}}\n\n")
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A slice statement that fills field `Chunks` of `pk`, after `prefix` (empty: no count of
    /// its own).
    fn slice(prefix: &str) -> Stmt {
        let place = r#"{"kind": "field", "name": "Chunks", "x": {"kind": "var", "name": "pk"}}"#;
        let json = format!(r#"{{"kind": "slice", "prefix": "{prefix}", "place": {place}}}"#);
        serde_json::from_str(&json).unwrap()
    }

    #[test]
    fn a_slice_whose_count_is_a_separate_statement_names_no_wire_form() {
        assert_eq!(wire_form(&[slice("")], "pk", "Chunks"), None);
        assert_eq!(
            wire_form(&[slice("Varuint32")], "pk", "Chunks").as_deref(),
            Some("a list after a `Varuint32` count")
        );
    }
}
